-- Racing game ("Chalet 2025") data, copied from the master-trackers database on 2026-10-19.
-- Load it into an empty racing_game database (the backend's sequelize.sync() would create the
-- same tables, but this keeps the races, racers and their images):
--   mysql -u <user> -p racing_game < db/seed.sql

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `player`;
CREATE TABLE `player` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT '',
  `balance` float DEFAULT '5000',
  `gains` float DEFAULT '0',
  `color` varchar(255) DEFAULT '#000000',
  `bidAmount` float DEFAULT '0',
  `bidRacer` int DEFAULT '-1',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `game`;
CREATE TABLE `game` (
  `id` int NOT NULL AUTO_INCREMENT,
  `currentRace` int DEFAULT '-1',
  `gameStatus` varchar(255) DEFAULT 'waiting',
  `players` json DEFAULT NULL,
  `races` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `race`;
CREATE TABLE `race` (
  `id` int NOT NULL AUTO_INCREMENT,
  `link` varchar(255) DEFAULT '',
  `racers` json DEFAULT NULL,
  `winner` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `racer`;
CREATE TABLE `racer` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL DEFAULT '',
  `image` longtext,
  `bidAmount` float DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `message`;
CREATE TABLE `message` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sender` int DEFAULT NULL,
  `message` varchar(255) DEFAULT '',
  `time` varchar(255) DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `sender` (`sender`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

SET FOREIGN_KEY_CHECKS = 1;
